<?php
declare(strict_types=1);
session_start();
require_once dirname(__DIR__) . '/api/config.php';
if (empty($_SESSION['admin_id'])) { header('Location: login.php'); exit; }
$orderId = (int) ($_GET['id'] ?? 0);
$statement = db()->prepare('SELECT * FROM orders WHERE id = ? LIMIT 1');
$statement->execute([$orderId]);
$order = $statement->fetch();
if (!$order) { http_response_code(404); exit('Order not found.'); }
$itemStatement = db()->prepare('SELECT product_name, quantity, unit_price, line_total FROM order_items WHERE order_id = ? ORDER BY id ASC');
$itemStatement->execute([$orderId]);
$items = $itemStatement->fetchAll();
function orderEscape(string $value): string { return htmlspecialchars($value, ENT_QUOTES, 'UTF-8'); }
$status = (string) ($order['order_status'] ?? $order['payment_status']);
$label = match ($status) { 'payment_approved' => 'Paid', 'payment_pending_confirmation' => 'Receipt submitted', 'payment_declined' => 'Declined', 'pending_payment' => 'Pending payment', 'payment_review' => 'Payment review', 'processing' => 'Processing', 'shipped' => 'Shipped', 'completed' => 'Completed', 'delivered' => 'Delivered', 'cancelled' => 'Cancelled', default => 'Awaiting payment' };
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Order <?= orderEscape((string) $order['order_code']) ?> - Electra admin</title><link rel="stylesheet" href="admin.css"><style>.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.detail-card{max-width:900px}.detail-card h2{margin:0 0 16px}.detail-list{display:grid;grid-template-columns:150px 1fr;gap:12px;margin:0}.detail-list dt{color:var(--muted)}.detail-list dd{margin:0;font-weight:600}.detail-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}.detail-actions a,.detail-actions button{padding:11px 16px;border:0;border-radius:7px;background:#11100e;color:#e6cd93;text-decoration:none;font:700 13px inherit;cursor:pointer}.detail-actions .danger{background:#fff7f6;border:1px solid #e3b9b3;color:#a33b30}.receipt-preview{display:block;max-width:100%;height:auto;margin-top:15px;border:1px solid var(--line)}.items-table{width:100%;border-collapse:collapse}.items-table th,.items-table td{padding:12px 8px;text-align:left;border-bottom:1px solid var(--line)}.items-table th{color:var(--muted);font-size:11px;text-transform:uppercase}@media(max-width:700px){.detail-grid{grid-template-columns:1fr}.detail-list{grid-template-columns:120px 1fr}}
</style></head><body><div class="admin-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">E</span><span>Electra</span></a><p class="nav-label">Store management</p><nav class="side-nav"><a href="index.php"><span>Overview</span></a><a href="products.php"><span>Products</span></a><a class="active" href="index.php?view=orders"><span>Orders</span></a><a href="index.php?view=payments"><span>Payments</span></a></nav><p class="nav-label bottom-label">General</p><nav class="side-nav"><a href="index.php?view=settings"><span>Settings</span></a><a class="sign-out" href="logout.php"><span>Sign out</span></a></nav><div class="sidebar-foot"><i></i> Store online</div></aside><main class="workspace"><header class="workspace-header"><div><p class="kicker">Electra store</p><h1>Order details</h1></div><div class="profile"><span class="avatar"><?= orderEscape(strtoupper(substr((string) $_SESSION['admin_name'], 0, 1))) ?></span><span><strong><?= orderEscape((string) $_SESSION['admin_name']) ?></strong><small>Store manager</small></span></div></header><section class="page-heading"><div><p class="section-kicker">Order <?= orderEscape((string) $order['order_code']) ?></p><h2>₦<?= number_format((float) $order['total'], 2) ?></h2><p><?= orderEscape($label) ?> · <?= date('M j, Y g:i a', strtotime((string) $order['created_at'])) ?></p></div><a class="select-pill" href="index.php?view=orders">Back to orders</a></section><div class="detail-grid"><section class="card detail-card"><h2>Customer and delivery</h2><dl class="detail-list"><dt>Name</dt><dd><?= orderEscape((string) $order['customer_name']) ?></dd><dt>Email</dt><dd><?= orderEscape((string) $order['customer_email']) ?></dd><dt>Phone</dt><dd><?= orderEscape((string) $order['customer_phone']) ?></dd><dt>Location</dt><dd><?= orderEscape((string) $order['delivery_location']) ?></dd><dt>Address</dt><dd><?= orderEscape((string) $order['delivery_address']) ?></dd></dl></section><section class="card detail-card"><h2>Payment</h2><dl class="detail-list"><dt>Status</dt><dd><?= orderEscape($label) ?></dd><dt>Method</dt><dd><?= orderEscape((string) $order['payment_method']) ?></dd><dt>Submitted</dt><dd><?= orderEscape((string) ($order['payment_submitted_at'] ?: 'Not submitted')) ?></dd><dt>Approved</dt><dd><?= orderEscape((string) ($order['payment_approved_at'] ?: 'Not approved')) ?></dd></dl><?php if (!empty($order['receipt_path'])): ?><a class="primary-button" style="margin-top:18px" href="../<?= orderEscape((string) $order['receipt_path']) ?>" target="_blank" rel="noopener">View receipt</a><?php else: ?><p class="muted">No receipt uploaded.</p><?php endif; ?></section></div><section class="card detail-card" style="margin-top:20px"><h2>Items</h2><?php if ($items): ?><div class="table-wrap"><table class="items-table"><thead><tr><th>Product</th><th>Quantity</th><th>Unit price</th><th>Total</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?= orderEscape((string) $item['product_name']) ?></td><td><?= (int) $item['quantity'] ?></td><td>₦<?= number_format((float) $item['unit_price'], 2) ?></td><td>₦<?= number_format((float) $item['line_total'], 2) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No item details were saved for this order.</p><?php endif; ?><div class="detail-actions"><?php if ($status !== 'payment_approved'): ?><form method="post" action="order-actions.php"><input type="hidden" name="action" value="approve"><input type="hidden" name="order_id" value="<?= $orderId ?>"><button type="submit">Approve payment</button></form><?php endif; ?><form method="post" action="order-actions.php" onsubmit="return confirm('Delete this order permanently?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="order_id" value="<?= $orderId ?>"><button class="danger" type="submit">Delete order</button></form></div></section></main></div></body></html>
